import json, random, string

def _rand_ascii(rng, min_len=0, max_len=16):
    n = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + " _-:/\\|.,;!@#$%^&*()[]{}<>?~`'\""
    s = ''.join(rng.choice(alphabet) for _ in range(n))
    return s

def _rand_unicode(rng, min_len=0, max_len=16):
    n = rng.randint(min_len, max_len)
    # Mix BMP and some extended planes excluding surrogate range
    def rand_cp():
        pools = [
            (0x20, 0x7E),          # printable ASCII
            (0x00A0, 0x024F),      # Latin-1 supplement, Latin Extended-A/B
            (0x0370, 0x03FF),      # Greek
            (0x0400, 0x04FF),      # Cyrillic
            (0x2000, 0x206F),      # General punctuation
            (0x2100, 0x214F),      # Letterlike symbols
            (0x2190, 0x21FF),      # Arrows
            (0x1F300, 0x1F64F),    # Emoji range
        ]
        a,b = rng.choice(pools)
        cp = rng.randint(a,b)
        if 0xD800 <= cp <= 0xDFFF:  # skip surrogates
            cp = 0x20
        return cp
    return ''.join(chr(rand_cp()) for _ in range(n))

def _random_number(rng):
    # Choose between int and float; include edgey magnitudes
    kind = rng.choice(["int","float"])
    if kind == "int":
        choices = [0, 1, -1, 2**31-1, -2**31, 2**63-1, -2**63]
        if rng.random() < 0.5:
            return rng.choice(choices)
        # random width
        sign = -1 if rng.random() < 0.3 else 1
        return int(sign * rng.randrange(0, 10**rng.randint(0, 10)))
    else:
        # floats with exponents and special magnitudes
        base = rng.uniform(-1e6, 1e6)
        if rng.random() < 0.4:
            base = rng.choice([0.0, -0.0, 1.0, -1.0, 1e-308, 1e308, -1e308, 3.14159])
        return float(base)

def _gen_primitive(rng):
    t = rng.choices([
        'null','bool','int','float','string_ascii','string_unicode'
    ], weights=[1,2,3,3,4,3])[0]
    if t == 'null':
        return None
    if t == 'bool':
        return bool(rng.getrandbits(1))
    if t == 'int':
        return _random_number(rng) if isinstance(_random_number(rng), int) else 0
    if t == 'float':
        v = _random_number(rng)
        return float(v)
    if t == 'string_ascii':
        # include escape-heavy content
        parts = []
        for _ in range(rng.randint(1,4)):
            parts.append(_rand_ascii(rng, 0, 8))
            parts.append(rng.choice(["\n","\t","\\","\"","/","\r","\\u263A"]))
        parts.append(_rand_ascii(rng, 0, 8))
        return ''.join(parts)
    if t == 'string_unicode':
        return _rand_unicode(rng, 0, 24)

def _gen_object(rng, depth, max_depth):
    obj = {}
    n = rng.randint(0, 6 if depth>0 else 8)
    for _ in range(n):
        # Keys can be numeric-looking, unicode, or with embedded null-like sequences
        key_type = rng.choice(["ascii","unicode","numeric_str"])
        if key_type == "ascii":
            k = _rand_ascii(rng, 1, 10)
        elif key_type == "unicode":
            k = _rand_unicode(rng, 1, 10)
        else:
            k = str(_random_number(rng))
        obj[k] = _gen_value(rng, depth+1, max_depth)
    return obj

def _gen_array(rng, depth, max_depth):
    arr = []
    n = rng.randint(0, 8 if depth>0 else 12)
    for _ in range(n):
        arr.append(_gen_value(rng, depth+1, max_depth))
    return arr

def _gen_value(rng, depth, max_depth):
    if depth >= max_depth:
        # leaf
        return _gen_primitive(rng)
    choice = rng.choices(['prim','obj','arr'], weights=[5,3,3])[0]
    if choice == 'prim':
        return _gen_primitive(rng)
    if choice == 'obj':
        return _gen_object(rng, depth, max_depth)
    return _gen_array(rng, depth, max_depth)

def _with_comments(rng, txt):
    # Insert C/C++ style comments around or within JSON where permissible
    if rng.random() < 0.6:
        header = rng.choice([
            "// top comment\n",
            "/* block top */\n",
            "\n"
        ])
    else:
        header = ""
    if rng.random() < 0.5:
        footer = rng.choice([
            "\n// tail comment\n",
            "\n/* block tail */\n",
            "\n"
        ])
    else:
        footer = ""
    # Optionally sprinkle an inline comment after a comma or colon
    if rng.random() < 0.5:
        txt = txt.replace(",", ", /*c*/" if rng.random()<0.5 else ", //c")
    if rng.random() < 0.3:
        txt = txt.replace(":", ": /*c*/" if rng.random()<0.5 else ": //c")
    return header + txt + footer

def _choose_top_level(rng):
    # Cover different root types, including strict roots (array/object) and scalars
    kind = rng.choices([
        'object','array','string','number','bool','null'
    ], weights=[4,4,3,3,2,1])[0]
    if kind == 'object':
        return _gen_object(rng, 0, rng.randint(1, 4))
    if kind == 'array':
        return _gen_array(rng, 0, rng.randint(1, 4))
    if kind == 'string':
        return _gen_primitive(rng if False else rng) or ""
    if kind == 'number':
        return _random_number(rng)
    if kind == 'bool':
        return bool(rng.getrandbits(1))
    return None

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a JSON value tree
    value = _choose_top_level(rng)

    # Dump with various formatting options to exercise readers and writers
    # Use separators to vary whitespace density
    if rng.random() < 0.5:
        # compact
        txt = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    else:
        indent = rng.choice([None, 0, 1, 2, 4])
        if indent in (None, 0):
            txt = json.dumps(value, ensure_ascii=False)
        else:
            txt = json.dumps(value, ensure_ascii=False, indent=indent)

    # Optionally add comments (permissive parsers will accept)
    if rng.random() < 0.5:
        txt = _with_comments(rng, txt)

    # Optionally prepend or append UTF-8 BOM or whitespace/newlines
    prefix = ""
    suffix = ""
    if rng.random() < 0.2:
        # UTF-8 BOM
        bom = "\ufeff"
        prefix = bom + ("\n" if rng.random() < 0.5 else "")
    if rng.random() < 0.6:
        suffix = "\n" * rng.randint(0, 3)

    out = (prefix + txt + suffix)

    # Ensure size limit
    b = out.encode('utf-8')
    if len(b) > 4096:
        # Trim by reducing arrays/objects serialization; fallback simple value
        rng2 = random.Random(seed ^ 0x9E3779B97F4A7C15)
        simple = {
            "k": _rand_ascii(rng2, 1, 16),
            "n": _random_number(rng2),
            "b": bool(rng2.getrandbits(1)),
            "s": _rand_unicode(rng2, 0, 24)
        }
        txt = json.dumps(simple, ensure_ascii=False, separators=(",", ":"))
        if rng.random() < 0.5:
            txt = _with_comments(rng, txt)
        b = txt.encode('utf-8')
    return b
